// Seasonal versions of the mark (generated by brand/render.py): same hand, dressed for the date.
// Windows are inclusive MM-DD and may wrap the year. Only the hand changes: wordmark, UI and copy stay.
export const editions = [
  { id: 'pride', from: '06-01', to: '06-30' },
  { id: 'halloween', from: '10-24', to: '11-01' },
  { id: 'natale', from: '12-08', to: '01-06' },
] as const

export type EditionId = (typeof editions)[number]['id']

export function editionAt(date: Date) {
  const md = `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
  return editions.find(e => e.from <= e.to ? md >= e.from && md <= e.to : md >= e.from || md <= e.to)
}

export const editionSrc = (id: EditionId) => `/brand/heyatom-edition-${id}.svg`
